from collections import deque

def ladder_length(begin_word, end_word, word_list):
    def one_apart(a, b):
        return sum(x != y for x, y in zip(a, b)) == 1

    steps = {begin_word: 1}               # word -> words in the shortest ladder to it
    queue = deque([begin_word])
    while queue:
        word = queue.popleft()
        if word == end_word:
            return steps[word]            # first arrival = shortest ladder
        for other in word_list:           # check every word in the list
            if other not in steps and one_apart(word, other):
                steps[other] = steps[word] + 1
                queue.append(other)
    return 0

int ladderLength(String beginWord, String endWord, List<String> wordList) {
    Map<String, Integer> steps = new HashMap<>();       // word -> words in the shortest ladder to it
    steps.put(beginWord, 1);
    ArrayDeque<String> queue = new ArrayDeque<>();
    queue.add(beginWord);
    while (!queue.isEmpty()) {
        String word = queue.poll();
        if (word.equals(endWord)) return steps.get(word);   // first arrival = shortest ladder
        for (String other : wordList) {                 // check every word in the list
            if (!steps.containsKey(other) && oneApart(word, other)) {
                steps.put(other, steps.get(word) + 1);
                queue.add(other);
            }
        }
    }
    return 0;
}

boolean oneApart(String a, String b) {
    int diff = 0;
    for (int i = 0; i < a.length(); i++) if (a.charAt(i) != b.charAt(i)) diff++;
    return diff == 1;
}

bool oneApart(const string& a, const string& b) {
    int diff = 0;
    for (size_t i = 0; i < a.size(); i++) if (a[i] != b[i]) diff++;
    return diff == 1;
}

