function ladderLength(beginWord, endWord, wordList) {
  const words = new Set(wordList);
  if (!words.has(endWord)) return 0;        // the ladder must end on a real word
  const queue = [beginWord];
  const steps = new Map([[beginWord, 1]]);  // word -> words in the shortest ladder to it
  let head = 0;
  while (head < queue.length) {
    const word = queue[head++];
    if (word === endWord) return steps.get(word);   // first arrival = shortest ladder
    for (let i = 0; i < word.length; i++) {
      for (let k = 0; k < 26; k++) {        // try every letter in every position
        const next = word.slice(0, i) + String.fromCharCode(97 + k) + word.slice(i + 1);
        if (words.has(next) && !steps.has(next)) {   // a real word, not reached yet
          steps.set(next, steps.get(word) + 1);
          queue.push(next);
        }
      }
    }
  }
  return 0;                                 // endWord can't be reached
}

int ladderLength(String beginWord, String endWord, List<String> wordList) {
    Set<String> words = new HashSet<>(wordList);
    if (!words.contains(endWord)) return 0;             // the ladder must end on a real word
    Map<String, Integer> steps = new HashMap<>();       // word -> words in the shortest ladder to it
    steps.put(beginWord, 1);
    ArrayDeque<String> queue = new ArrayDeque<>();
    queue.add(beginWord);
    while (!queue.isEmpty()) {
        String word = queue.poll();
        if (word.equals(endWord)) return steps.get(word);   // first arrival = shortest ladder
        char[] letters = word.toCharArray();
        for (int i = 0; i < letters.length; i++) {
            char original = letters[i];
            for (char ch = 'a'; ch <= 'z'; ch++) {      // try every letter in every position
                letters[i] = ch;
                String next = new String(letters);
                if (words.contains(next) && !steps.containsKey(next)) {   // a real word, not reached yet
                    steps.put(next, steps.get(word) + 1);
                    queue.add(next);
                }
            }
            letters[i] = original;
        }
    }
    return 0;                                           // endWord can't be reached
}

